const std = @import("std");
const tac = @import("tac_parser.zig");
pub const Set = std.StaticBitSet(1024);
pub const Block = struct { first: usize, end: usize, labels: []const tac.Text, preds: std.ArrayList(usize) = .empty, succs: std.ArrayList(usize) = .empty, reachable: bool = false, dom: Set = Set.initEmpty(), idom: ?usize = null, depth: usize = 0 };
pub const Loop = struct { header: usize, latches: Set = Set.initEmpty(), blocks: Set = Set.initEmpty(), exits: Set = Set.initEmpty(), outside: Set = Set.initEmpty(), depth: usize = 0 };
pub const Graph = struct { blocks: []Block, owner: []usize, post: []const usize, reverse: []const usize, loops: []Loop };
fn visit(a: tac.Allocator, blocks: []Block, b: usize, post: *std.ArrayList(usize)) anyerror!void { blocks[b].reachable = true; for (blocks[b].succs.items) |s| if (!blocks[s].reachable) { try visit(a, blocks, s, post); }; try post.append(a, b); }
fn target(f: tac.Function, owner: []const usize, label: tac.Text) usize { for (f.code, 0..) |i, n| for (i.labels) |l| if (tac.eq(label, l)) return owner[n]; unreachable; }
pub fn build(a: tac.Allocator, f: tac.Function) !Graph {
    var blocks: std.ArrayList(Block) = .empty; const owner = try a.alloc(usize, f.code.len);
    for (f.code, 0..) |i, n| {
        const leader = n == 0 or i.labels.len > 0 or f.code[n - 1].kind == .goto or f.code[n - 1].kind == .@"if" or f.code[n - 1].kind == .@"return";
        if (leader) try blocks.append(a, .{ .first = n, .end = n, .labels = i.labels }); owner[n] = blocks.items.len - 1; blocks.items[owner[n]].end = n + 1;
    }
    for (blocks.items, 0..) |*b, n| {
        const last = f.code[b.end - 1];
        if (last.kind == .goto) try b.succs.append(a, target(f, owner, last.target))
        else if (last.kind == .@"if") { try b.succs.append(a, n + 1); const to = target(f, owner, last.target); if (to != n + 1) try b.succs.append(a, to); }
        else if (last.kind != .@"return") try b.succs.append(a, n + 1);
    }
    for (blocks.items, 0..) |b, n| for (b.succs.items) |s| { try blocks.items[s].preds.append(a, n); };
    var post: std.ArrayList(usize) = .empty; try visit(a, blocks.items, 0, &post); const reverse = try a.dupe(usize, post.items); std.mem.reverse(usize, reverse);
    var all = Set.initEmpty(); for (reverse) |b| all.set(b); for (reverse) |b| blocks.items[b].dom = all; blocks.items[0].dom = .initEmpty(); blocks.items[0].dom.set(0);
    while (true) { var changed = false; for (reverse[1..]) |n| { var dom = all; for (blocks.items[n].preds.items) |p| if (blocks.items[p].reachable) { dom.setIntersection(blocks.items[p].dom); }; dom.set(n); if (!dom.eql(blocks.items[n].dom)) { blocks.items[n].dom = dom; changed = true; } } if (!changed) break; }
    for (reverse[1..]) |n| { var best: usize = 0; var it = blocks.items[n].dom.iterator(.{}); while (it.next()) |p| if (p != n and blocks.items[p].dom.count() > best) { best = blocks.items[p].dom.count(); blocks.items[n].idom = p; }; }
    var loops: std.ArrayList(Loop) = .empty;
    for (blocks.items, 0..) |h, hi| {
        if (!h.reachable) continue; var loop: Loop = .{ .header = hi }; loop.blocks.set(hi);
        for (blocks.items, 0..) |t, ti| if (t.reachable and t.dom.isSet(hi)) { for (t.succs.items) |s| if (s == hi) { loop.latches.set(ti); loop.blocks.set(ti); }; };
        if (loop.latches.count() == 0) continue;
        while (true) { const before = loop.blocks; var it = before.iterator(.{}); while (it.next()) |n| if (n != hi) { for (blocks.items[n].preds.items) |p| if (blocks.items[p].reachable) { loop.blocks.set(p); }; }; if (before.eql(loop.blocks)) break; }
        var it = loop.blocks.iterator(.{}); while (it.next()) |n| { blocks.items[n].depth += 1; if (f.code[blocks.items[n].end - 1].kind == .@"return") loop.exits.set(n); for (blocks.items[n].succs.items) |s| if (!loop.blocks.isSet(s)) { loop.exits.set(n); loop.outside.set(s); }; }
        try loops.append(a, loop);
    }
    for (loops.items) |*loop| for (loops.items) |other| { if (other.blocks.isSet(loop.header)) loop.depth += 1; };
    return .{ .blocks = blocks.items, .owner = owner, .post = post.items, .reverse = reverse, .loops = loops.items };
}

const std = @import("std");
const tac = @import("tac_parser.zig");
const cfg = @import("cfg.zig");
pub const Set = cfg.Set;
pub const Definition = struct { variable: tac.Text, number: usize };
pub const Copy = struct { dest: tac.Text, source: tac.Text };
pub const Analysis = struct { input: []Set, output: []Set, before: []Set, after: []Set, iterations: usize = 0 };
pub const Flow = struct { a: tac.Allocator, function: tac.Function, graph: cfg.Graph, variables: []const tac.Text, definitions: []const Definition, expressions: []const tac.Instruction, copies: []const Copy, reaching: Analysis, live: Analysis, available: Analysis, copying: Analysis,
    pub fn variable(flow: *const Flow, name: tac.Text) usize { for (flow.variables, 0..) |v, i| if (tac.eq(v, name)) return i; unreachable; }
    pub fn expression(flow: *const Flow, ins: tac.Instruction) ?usize { for (flow.expressions, 0..) |e, i| if (sameExpression(e, ins)) return i; return null; }
    pub fn transfer(flow: *const Flow, set: *Set, ins: tac.Instruction, number: usize, mode: usize) void {
        const used = ins.used();
        if (mode == 0) { if (ins.dest.len > 0) { for (flow.definitions, 0..) |d, i| { if (tac.eq(d.variable, ins.dest)) set.unset(i); } for (flow.definitions, 0..) |d, i| { if (d.number == number and tac.eq(d.variable, ins.dest)) set.set(i); } } }
        else if (mode == 1) { if (ins.dest.len > 0) set.unset(flow.variable(ins.dest)); for (used) |v| if (tac.variable(v)) { set.set(flow.variable(v)); }; }
        else if (mode == 2) {
            if (flow.expression(ins)) |i| set.set(i);
            for (flow.expressions, 0..) |e, i| {
                if ((ins.kind == .store and e.kind == .load and tac.eq(e.array, ins.array)) or (ins.kind == .call and e.kind == .load)) set.unset(i);
                if (ins.dest.len > 0) for (e.used()) |v| { if (tac.eq(v, ins.dest)) set.unset(i); };
            }
        } else {
            if (ins.dest.len > 0) for (flow.copies, 0..) |copy, i| { if (tac.eq(copy.dest, ins.dest) or tac.eq(copy.source, ins.dest)) set.unset(i); };
            if (ins.kind == .copy and tac.variable(ins.a) and !tac.eq(ins.dest, ins.a)) for (flow.copies, 0..) |copy, i| { if (tac.eq(copy.dest, ins.dest) and tac.eq(copy.source, ins.a)) set.set(i); };
        }
    }
};
pub fn sameExpression(a: tac.Instruction, b: tac.Instruction) bool { return a.kind == b.kind and (a.kind == .bin or a.kind == .load) and tac.eq(a.op, b.op) and tac.eq(a.array, b.array) and tac.eq(a.a, b.a) and tac.eq(a.b, b.b); }
fn unique(a: tac.Allocator, list: *std.ArrayList(tac.Text), name: tac.Text) !void { if (!tac.variable(name)) return; for (list.items) |n| if (tac.eq(n, name)) return; try list.append(a, name); }
fn allocate(a: tac.Allocator, blocks: usize, instructions: usize) !Analysis { const input = try a.alloc(Set, blocks); const output = try a.alloc(Set, blocks); const before = try a.alloc(Set, instructions); const after = try a.alloc(Set, instructions); @memset(input, .initEmpty()); @memset(output, .initEmpty()); @memset(before, .initEmpty()); @memset(after, .initEmpty()); return .{ .input = input, .output = output, .before = before, .after = after }; }
fn solve(f: *Flow, mode: usize) void {
    const analysis = switch (mode) { 0 => &f.reaching, 1 => &f.live, 2 => &f.available, else => &f.copying };
    var universe = Set.initEmpty(); if (mode >= 2) { const n = if (mode == 2) f.expressions.len else f.copies.len; for (0..n) |i| universe.set(i); for (analysis.output) |*s| s.* = universe; }
    while (true) {
        analysis.iterations += 1; var changed = false; const order = if (mode == 1) f.graph.post else f.graph.reverse;
        for (order) |bi| {
            const b = f.graph.blocks[bi]; var set = if (mode >= 2 and bi != 0) universe else Set.initEmpty();
            if (mode == 1) { for (b.succs.items) |s| set.setUnion(analysis.input[s]); analysis.output[bi] = set; var n = b.end; while (n > b.first) { n -= 1; f.transfer(&set, f.function.code[n], n + 1, mode); } if (!set.eql(analysis.input[bi])) changed = true; analysis.input[bi] = set; }
            else {
                if (bi != 0 or mode == 0) for (b.preds.items) |p| { if (!f.graph.blocks[p].reachable) continue; if (mode == 0) set.setUnion(analysis.output[p]) else set.setIntersection(analysis.output[p]); };
                if (bi == 0 and mode == 0) for (f.definitions, 0..) |d, i| { if (d.number == 0) set.set(i); };
                analysis.input[bi] = set; for (b.first..b.end) |n| f.transfer(&set, f.function.code[n], n + 1, mode); if (!set.eql(analysis.output[bi])) changed = true; analysis.output[bi] = set;
            }
        }
        if (!changed) break;
    }
    for (f.graph.reverse) |bi| { const b = f.graph.blocks[bi]; var set = if (mode == 1) analysis.output[bi] else analysis.input[bi]; if (mode == 1) { var n = b.end; while (n > b.first) { n -= 1; analysis.after[n] = set; f.transfer(&set, f.function.code[n], n + 1, mode); analysis.before[n] = set; } } else for (b.first..b.end) |n| { analysis.before[n] = set; f.transfer(&set, f.function.code[n], n + 1, mode); analysis.after[n] = set; }; }
}
pub fn analyze(a: tac.Allocator, function: tac.Function) !Flow {
    const graph = try cfg.build(a, function); var vars: std.ArrayList(tac.Text) = .empty; var definitions: std.ArrayList(Definition) = .empty; var expressions: std.ArrayList(tac.Instruction) = .empty; var copies: std.ArrayList(Copy) = .empty;
    for (function.params) |p| { try unique(a, &vars, p); try definitions.append(a, .{ .variable = p, .number = 0 }); }
    for (function.code, 0..) |ins, n| {
        if (!graph.blocks[graph.owner[n]].reachable) continue; try unique(a, &vars, ins.dest); for (ins.used()) |v| try unique(a, &vars, v);
        if (ins.dest.len > 0) try definitions.append(a, .{ .variable = ins.dest, .number = n + 1 });
        if (ins.kind == .bin or ins.kind == .load) { var found = false; for (expressions.items) |e| if (sameExpression(e, ins)) { found = true; break; }; if (!found) try expressions.append(a, ins); }
        if (ins.kind == .copy and tac.variable(ins.a) and !tac.eq(ins.dest, ins.a)) { var found = false; for (copies.items) |c| if (tac.eq(c.dest, ins.dest) and tac.eq(c.source, ins.a)) { found = true; break; }; if (!found) try copies.append(a, .{ .dest = ins.dest, .source = ins.a }); }
    }
    std.mem.sort(tac.Text, vars.items, {}, tac.less);
    var flow: Flow = .{ .a = a, .function = function, .graph = graph, .variables = vars.items, .definitions = definitions.items, .expressions = expressions.items, .copies = copies.items, .reaching = try allocate(a, graph.blocks.len, function.code.len), .live = try allocate(a, graph.blocks.len, function.code.len), .available = try allocate(a, graph.blocks.len, function.code.len), .copying = try allocate(a, graph.blocks.len, function.code.len) };
    for (0..4) |mode| solve(&flow, mode); return flow;
}

const std = @import("std");
const tac = @import("tac_parser.zig");
const cfg = @import("cfg.zig");
const df = @import("dataflow.zig");
const opt = @import("optimizations.zig");
const registers = @import("regalloc.zig");
const Text = tac.Text;
const pass_names = [_]Text{"constprop", "copyprop", "cse", "dce", "licm", "unreachable"};
fn list(b: *tac.Buffer, names: []const Text) !void { if (names.len == 0) try b.add("-"); for (names, 0..) |n, i| { if (i > 0) try b.add(","); try b.add(n); } }
fn blocks(b: *tac.Buffer, set: cfg.Set) !void { var it = set.iterator(.{}); var first = true; while (it.next()) |n| { if (!first) try b.add(","); try b.print("B{d}", .{n + 1}); first = false; } if (first) try b.add("-"); }
fn sequence(b: *tac.Buffer, values: []const usize, block: bool) !void { if (values.len == 0) try b.add("-"); for (values, 0..) |v, i| { if (i > 0) try b.add(","); if (block) try b.print("B{d}", .{v + 1}) else try b.print("{d}", .{v}); } }
fn tree(b: *tac.Buffer, graph: cfg.Graph, node: usize, depth: usize) anyerror!void { for (0..depth * 2) |_| try b.add(" "); try b.print("B{d}\n", .{node + 1}); for (graph.blocks, 0..) |child, i| if (child.reachable and child.idom == node) { try tree(b, graph, i, depth + 1); }; }
fn setText(b: *tac.Buffer, flow: *const df.Flow, set: cfg.Set, mode: usize) !void {
    var names: std.ArrayList(Text) = .empty;
    if (mode == 0) {
        const indices = try b.a.alloc(usize, set.count()); var p: usize = 0; var it = set.iterator(.{}); while (it.next()) |i| { indices[p] = i; p += 1; }
        std.mem.sort(usize, indices, flow, struct { fn cmp(f: *const df.Flow, x: usize, y: usize) bool { const a = f.definitions[x]; const c = f.definitions[y]; return if (a.number == c.number) tac.less({}, a.variable, c.variable) else a.number < c.number; } }.cmp);
        for (indices) |i| { const d = flow.definitions[i]; try names.append(b.a, try std.fmt.allocPrint(b.a, "{s}:{d}", .{d.variable, d.number})); }
    } else { var it = set.iterator(.{}); while (it.next()) |i| try names.append(b.a, if (mode == 1) flow.variables[i] else (try flow.expressions[i].expression(b.a)).?); std.mem.sort(Text, names.items, {}, tac.less); }
    try list(b, names.items);
}
fn analysis(b: *tac.Buffer, f: tac.Function, kind: Text) !void {
    const flow = try df.analyze(b.a, f); const graph = flow.graph; try b.print("== {s} ({s}) ==\ncode:\n", .{f.name, kind});
    for (f.code, 0..) |ins, n| {
        for (ins.labels) |label| try b.print("{s}:\n", .{label}); try b.print("  #{d} {s}", .{n + 1, try ins.text(b.a)});
        if (graph.blocks[graph.owner[n]].reachable) { var seen: std.ArrayList(Text) = .empty; for (ins.used()) |v| {
            if (!tac.variable(v)) continue; var duplicate = false; for (seen.items) |old| if (tac.eq(v, old)) { duplicate = true; }; if (duplicate) continue;
            try b.add(if (seen.items.len == 0) " | " else " "); try seen.append(b.a, v); try b.print("{s}:", .{v}); var numbers: std.ArrayList(usize) = .empty; var it = flow.reaching.before[n].iterator(.{}); while (it.next()) |i| { const d = flow.definitions[i]; if (tac.eq(v, d.variable)) try numbers.append(b.a, d.number); } std.mem.sort(usize, numbers.items, {}, std.sort.asc(usize)); try sequence(b, numbers.items, false);
        } }
        try b.add("\n");
    }
    try b.print("blocks: {d}\n", .{graph.blocks.len}); var unreachable_blocks = cfg.Set.initEmpty();
    for (graph.blocks, 0..) |block, i| { try b.print("B{d} {d}-{d} labels=", .{i + 1, block.first + 1, block.end}); try list(b, block.labels); try b.add(" preds="); try sequence(b, block.preds.items, true); try b.add(" succs="); try sequence(b, block.succs.items, true); try b.add("\n"); if (!block.reachable) unreachable_blocks.set(i); }
    try b.add("unreachable: "); try blocks(b, unreachable_blocks); try b.add("\norder: "); try sequence(b, graph.reverse, true); try b.line("\ndominators:");
    for (graph.blocks, 0..) |block, i| if (block.reachable) { try b.print("B{d} idom=", .{i + 1}); if (block.idom) |parent| try b.print("B{d}", .{parent + 1}) else try b.add("-"); try b.add(" dom="); try blocks(b, block.dom); try b.add("\n"); };
    try b.line("dominator tree:"); try tree(b, graph, 0, 0); try b.print("loops: {d}\n", .{graph.loops.len});
    for (graph.loops) |loop| { try b.print("header=B{d} latches=", .{loop.header + 1}); try blocks(b, loop.latches); try b.print(" depth={d} blocks=", .{loop.depth}); try blocks(b, loop.blocks); try b.add(" exits="); try blocks(b, loop.exits); try b.add("\n"); }
    for ([_]Text{"reaching definitions", "liveness", "available expressions"}, [_]df.Analysis{flow.reaching, flow.live, flow.available}, 0..) |name, sets, mode| {
        try b.print("{s}: iterations={d}\n", .{name, sets.iterations}); for (graph.blocks, 0..) |block, i| if (block.reachable) { try b.print("B{d} in=", .{i + 1}); try setText(b, &flow, sets.input[i], mode); try b.add(" out="); try setText(b, &flow, sets.output[i], mode); try b.add("\n"); };
    }
}
const Calls = struct { edges: []cfg.Set, reachable: cfg.Set };
fn functionIndex(program: tac.Program, name: Text) usize { for (program.functions, 0..) |f, i| if (tac.eq(f.name, name)) return i; unreachable; }
fn callGraph(a: tac.Allocator, p: tac.Program) !Calls {
    const edges = try a.alloc(cfg.Set, p.functions.len); @memset(edges, .initEmpty()); for (p.functions, 0..) |f, i| for (f.code) |ins| { if (ins.kind == .call) edges[i].set(functionIndex(p, ins.target)); };
    var reach = cfg.Set.initEmpty(); reach.set(functionIndex(p, "main")); while (true) { const before = reach; var it = before.iterator(.{}); while (it.next()) |n| reach.setUnion(edges[n]); if (before.eql(reach)) break; } return .{ .edges = edges, .reachable = reach };
}
fn callGraphText(b: *tac.Buffer, p: tac.Program, heading: Text) !Calls {
    const graph = try callGraph(b.a, p); try b.print("== call graph ({s}) ==\n", .{heading}); var unreachable_functions: std.ArrayList(Text) = .empty;
    for (p.functions, 0..) |f, i| {
        try b.print("{s} -> ", .{f.name}); var names: std.ArrayList(Text) = .empty; var it = graph.edges[i].iterator(.{}); while (it.next()) |n| try names.append(b.a, p.functions[n].name); try list(b, names.items);
        var closure = graph.edges[i]; while (true) { const before = closure; it = before.iterator(.{}); while (it.next()) |n| closure.setUnion(graph.edges[n]); if (before.eql(closure)) break; } if (closure.isSet(i)) try b.add(" (recursive)"); try b.add("\n"); if (!graph.reachable.isSet(i)) try unreachable_functions.append(b.a, f.name);
    }
    try b.add("unreachable functions: "); try list(b, unreachable_functions.items); try b.add("\n"); return graph;
}
fn rename(a: tac.Allocator, alloc: registers.Allocation, name: Text) !Text { if (!tac.variable(name)) return name; for (alloc.names, alloc.registers) |n, r| if (tac.eq(n, name)) return if (r) |v| try std.fmt.allocPrint(a, "R{d}", .{v}) else name; return name; }
fn spilled(alloc: registers.Allocation, name: Text) bool { for (alloc.names, alloc.registers) |n, r| if (tac.eq(n, name)) return r == null; return false; }
fn allocated(b: *tac.Buffer, f: tac.Function, k: usize) !tac.Function {
    var flow = try df.analyze(b.a, f); const alloc = try registers.allocate(b.a, f, &flow, k); var edges: usize = 0; for (alloc.neighbors) |ns| edges += ns.count();
    try b.print("== {s} ==\nnodes={d} edges={d} registers={d}\n", .{f.name, alloc.names.len, edges / 2, k});
    for (alloc.names, 0..) |n, i| { try b.print("{s} degree={d} cost={d} neighbors=", .{n, alloc.neighbors[i].count(), alloc.costs[i]}); var names: std.ArrayList(Text) = .empty; var it = alloc.neighbors[i].iterator(.{}); while (it.next()) |j| try names.append(b.a, alloc.names[j]); try list(b, names.items); try b.add("\n"); }
    try b.add("simplify: "); for (alloc.order, 0..) |i, n| { if (n > 0) try b.add(","); try b.add(alloc.names[i]); } if (alloc.order.len == 0) try b.add("-"); try b.add("\npotential spills: ");
    for (alloc.potential, 0..) |p, i| { if (i > 0) try b.add(","); try b.print("{s}({d}/{d})", .{alloc.names[p.node], alloc.costs[p.node], p.degree}); } if (alloc.potential.len == 0) try b.add("-"); try b.add("\n");
    var used = cfg.Set.initEmpty(); var spills: usize = 0;
    for (alloc.names, alloc.registers) |name, r| { try b.print("{s} -> ", .{name}); if (r) |reg| { used.set(reg); try b.print("R{d}\n", .{reg}); } else { spills += 1; try b.line("spill"); } }
    const params = try b.a.alloc(Text, f.params.len); var spill_defs: usize = 0; var spill_uses: usize = 0; var moves: usize = 0; for (f.params, 0..) |p, i| { params[i] = try rename(b.a, alloc, p); if (spilled(alloc, p)) spill_defs += 1; }
    var code: std.ArrayList(tac.Instruction) = .empty; var pending: std.ArrayList(Text) = .empty;
    for (f.code) |old| { var ins = old; try pending.appendSlice(b.a, old.labels); if (ins.dest.len > 0) { ins.dest = try rename(b.a, alloc, ins.dest); if (spilled(alloc, old.dest)) spill_defs += 1; }
        for (old.used(), 0..) |v, index| if (tac.variable(v)) { const new = try rename(b.a, alloc, v); ins.operand(index).* = new; if (spilled(alloc, v)) spill_uses += 1; };
        if (ins.kind == .copy and tac.eq(ins.dest, ins.a)) { moves += 1; continue; } ins.labels = pending.items; pending = .empty; try code.append(b.a, ins);
    }
    try b.print("summary: pressure={d} used={d} spilled={d} moves={d} spill_uses={d} spill_defs={d}\n", .{alloc.pressure, used.count(), spills, moves, spill_uses, spill_defs});
    const result: tac.Function = .{ .name = f.name, .params = params, .code = code.items }; try tac.functionText(b, result); return result;
}
const Execution = struct {
    a: tac.Allocator, program: tac.Program, inputs: []const i64, position: usize = 0, arrays: [][]i64,
    steps: []usize, calls: []usize, kinds: [11]usize = @splat(0), output: std.ArrayList(i64) = .empty,
    fn value(table: *std.StringHashMapUnmanaged(i64), operand: Text) i64 { return if (tac.variable(operand)) table.get(operand).? else if (operand.len == 0) 0 else tac.number(operand); }
    fn array(e: *Execution, name: Text) []i64 { for (e.program.arrays, 0..) |ar, i| if (tac.eq(ar.name, name)) return e.arrays[i]; unreachable; }
    fn call(e: *Execution, fi: usize, args: []const i64) anyerror!i64 {
        const f = e.program.functions[fi]; e.calls[fi] += 1; var table: std.StringHashMapUnmanaged(i64) = .empty; var pushed: std.ArrayList(i64) = .empty; for (f.params, args) |p, v| try table.put(e.a, p, v); var pc: usize = 0;
        while (pc < f.code.len) {
            const ins = f.code[pc]; e.steps[fi] += 1; e.kinds[@intFromEnum(ins.kind)] += 1; pc += 1;
            switch (ins.kind) {
